"""Engineering examples linked to the reviewed implementation."""
from components import *
import json

def stories():
    return json.loads((ROOT/'scripts/engineering_stories.json').read_text())

def engineering_showcase():
    items=stories()
    groups=['All','Security','Domain','Architecture','Reliability','Real-time']
    filters=''.join(f'<button type="button" class="story-filter" data-story-filter="{g}" aria-pressed="{str(g=="All").lower()}">{g}<span>{len(items) if g=="All" else sum(s["category"]==g for s in items)}</span></button>' for g in groups)
    tabs=[]
    panels=[]
    for i,s in enumerate(items):
        id='story-'+s['id']
        href=s['source_url']
        tabs.append(f'<button class="engine-tab" type="button" role="tab" id="tab-{id}" aria-selected="{str(i==0).lower()}" aria-controls="{id}" data-story-category="{s["category"]}"><span>{i+1:02}</span><span><strong>{s["title"]}</strong><small>{s["summary"]}</small></span>{arrow("right")}</button>')
        panels.append(f'''<div class="code-window engineering-panel" id="{id}" role="tabpanel" aria-labelledby="tab-{id}" tabindex="0"><div class="code-header"><span>{s['file_label']}</span><span>{s['project']} / C#</span></div><div class="code-context"><span class="label">{s['category']} / The decision</span><h3>{s['title']}</h3><p>{s['explanation']}</p><div class="code-purpose"><strong>Why it matters</strong>{s['benefit']}</div></div>{codeblock(s['code'])}<div class="code-note"><span>Source excerpt · reformatted for readability</span>{ext(href,"Read the full implementation")}</div></div>''')
    return f'''<section class="section engineering" id="engineering" aria-labelledby="engineering-title"><div class="wrap"><div class="section-head reveal"><div><div class="eyebrow">02 / Under the surface</div><h2 id="engineering-title">The thinking<br>behind the code.</h2></div><p>Small decisions shape the whole system. Explore twelve examples of how I approach domain rules, data boundaries, and the details that connect them.</p></div><div class="engine-controls" hidden><div class="story-filters" role="group" aria-label="Filter engineering examples">{filters}</div><p class="story-count mono" aria-live="polite">12 decisions / actual project code</p></div><div class="engine-layout engineering-explorer reveal"><div><div class="engine-tabs" role="tablist" aria-label="Explore engineering decisions">{''.join(tabs)}</div><p class="engine-navigation-hint">Explore the list, or choose a theme above.</p></div><div class="engine-panels">{''.join(panels)}</div></div><div class="engine-bottom"><p>Examples from Collabrium, the four-person graduation platform I led, and Actify, a course-based implementation. Each source link opens the exact version reviewed.</p><a class="text-link" href="collabrium.html#decisions">More inside the Collabrium case study {arrow()}</a></div></div></section>'''

def collabrium_decisions():
    groups=[
    ("Identity & API boundaries",[
        ("Tenant membership establishes request context.","Multi-tenancy · Request scoping","The middleware resolves the authenticated user and tenant, checks activation and membership, and sets the scoped tenant context. Ordinary tenant-aware HTTP requests use the resulting context; hub routes and explicitly exempt endpoints follow separate paths.","A request for a different organization is rejected before ordinary tenant-scoped work continues.",C+"API/Middlewares/TentantMiddleware.cs"),
        ("Project access has its own authorization requirement.","Policies · Resource authorization","The project-access handler verifies that the requested project belongs to the user’s tenant, then applies role and project-membership rules. Knowing a project ID does not establish access.","Project resources have an explicit authorization boundary in addition to authentication.",C+"Infrastructure/Security/AuthRequirements/MustHaveProjectAccess.cs"),
        ("Refresh tokens rotate through persisted state.","Identity · Credential lifecycle","A successful token refresh revokes the stored token, records its replacement, and persists a new refresh token with an expiry. The service rejects an inactive token before the refresh path proceeds.","Rotation and revocation have a visible representation in persistence.",C+"Infrastructure/Identity/IdentityService.cs"),
        ("Validation and error contracts have shared infrastructure.","FluentValidation · Problem Details","The registered request validator, when present, runs in the MediatR pipeline. Global exception handling groups validation errors by field and maps other failures into Problem Details with a trace identifier. Exception type and stack traces are added only in development.","Clients receive structured error information while the API keeps exception handling out of individual controllers.",C+"API/Middlewares/GlobalExceptionHandler.cs")
    ]),
    ("Domain rules & workflow integrity",[
        ("The work hierarchy is a domain rule.","Domain modeling · Relationship invariants","The domain validates allowed Epic, User Story, Task, Bug, and Test Case relationships. It rejects invalid type pairings, self-relations, duplicate relations, and prohibited parent/child configurations.","Hierarchy rules remain part of the model as users connect work across boards and detail views.",C+"Domain/Models/WorkItem.cs"),
        ("A release state reflects the work underneath it.","Polymorphism · State transition gates","UserStory applies different gates for testing, release, and completion. Completion checks child tasks and bugs are done and child test cases have passed, then delegates the state change to the shared workflow behavior.","A story’s completion reflects its child delivery and quality work.",C+"Domain/Models/UserStory.cs"),
        ("Completed sprint work keeps its historical context.","Lifecycle modeling · Analytical integrity","CompleteSprint moves only incomplete items back to the backlog. Completed items stay linked to the sprint while its completion and history update share a transaction.","Moving unfinished scope forward preserves the meaning of historical delivery reports.",C+"Application/Features/Sprints/Commands/CompleteSprint.cs"),
        ("Partial updates preserve the user’s intent.","API semantics · Explicit patch decisions","PatchHelpers distinguishes an omitted string from a request to clear it or set a new value. Work-item updates also validate sprint relationships and move a user story’s recognized children with it when appropriate.","Editing one field can leave another unchanged, and moving related work can preserve the hierarchy’s sprint invariant.",C+"Application/Common/PatchHelpers.cs")
    ]),
    ("Data access & change consistency",[
        ("A use case defines the database transaction.","Unit of Work · Transaction boundaries","Multi-step writes run through ExecuteInTransactionAsync. It executes the operation, saves, and commits, or rolls back when an exception escapes. Work-item creation coordinates a generated project code, the item, and its creation history.","Related database changes have a clear commit boundary.",C+"Infrastructure/Persistence/UnitOfWork.cs"),
        ("Read models answer a particular screen or question.","CQRS · EF Core projections","Read models combine tenant and project scoping with filtering, projections, and AsNoTracking where appropriate. The display-name lookup selects only a work item’s code and title rather than its full entity graph.","Each read can express the shape and scope of the data its caller needs.",C+"Infrastructure/Persistence/ReadModels/WorkItemsReadModel.cs"),
        ("History turns changed values into useful context.","Change detection · Audit history","ProjectHistoryRecorder compares snapshots, skips unchanged values and ignored technical properties, and resolves values for display before creating history records. A responsible user and related work context accompany the change.","A teammate can understand what changed without interpreting raw related-record identifiers.",C+"Application/Services/ProjectHistoryRecorder.cs")
    ]),
    ("Integration & runtime behavior",[
        ("Generated suggestions pass through application checks.","AI integration · Parsing, repair & fallback","Work-item AI output goes through JSON extraction, typed deserialization, normalization, and usability checks. Invalid responses trigger repair prompts within a bounded attempt loop, with fallback suggestions afterward. Normal commands validate the final user-approved data.","AI can assist the workflow while the application controls usable structure and persistence.",C+"Infrastructure/AI/WorkItemFieldsSuggestionService.cs"),
        ("Real-time updates follow their resource context.","SignalR · Connection & group scope","Presence, comments, and notifications use separate hubs. The comment hub resolves tenant context and works with the selected project and work item when loading discussion and routing updates.","Live collaboration stays connected to the work resource the user opened.",C+"Infrastructure/SignalR/Hubs/CommentHub.cs"),
        ("Events separate the business change from its responses.","MediatR events · Separation of concerns","Sprint completion publishes an application event with relevant context. Separate notification and email handlers own their response. Notification handling filters and deduplicates recipients before delivery.","Each follow-up has a distinct responsibility. The current events are in-process MediatR notifications, without a durable broker guarantee.",C+"Application/EventsHandlers/SprintStatusChangedNotificationHandler.cs"),
        ("Scheduled reminders belong to a managed worker lifecycle.","BackgroundService · DI scopes · Cancellation","Hosted workers use PeriodicTimer and cancellation tokens. Each reminder run creates a service scope, finds due events, targets attendees, and marks processed reminders. Scheduled announcement delivery has a corresponding worker.","Time-based behavior runs independently of page visits, within the ASP.NET Core host.",C+"Infrastructure/BackgroundServices/EventReminderBackgroundService.cs"),
        ("A report dataset supports several delivery formats.","Reporting · Read models · PDF & AI adapters","Scoped report data feeds JSON views, ScottPlot charts, QuestPDF exports, and AI interpretations. The current enum defines ten analytical report types, with sprint-summary functionality exposed separately.","The same analytical context can serve the interface, a portable document, and an assisted explanation.",C+"Domain/Enums/ReportType.cs")
    ]),
    ("Rules applied in the running workflows",[
        ("A status change checks responsibility before transition.","Authorization · Workflow preconditions","UpdateWorkItemStatus rejects unassigned or blocked items, permits managers or the current assignee, checks allowed transitions, and requires a passed result before completing a test case. It then applies domain validation and records the change in a transaction.","The status endpoint combines permission checks with business preconditions.",C+"Application/Features/WorkItems/Commands/UpdateWorkItemStatus.cs"),
        ("Attachment uploads verify the resource and the actor.","Resource ownership · Upload workflow","AddWorkItemAttachment resolves the project and work item within the tenant, rejects empty uploads, and permits a manager, current assignee, or creator before calling storage. Attachment metadata and creation history are then saved in a database transaction.","Upload permission is checked before the external storage operation. The database transaction covers metadata and history, not the external upload.",C+"Application/Features/WorkItems/Commands/Attachments/AddWorkItemAttachment.cs"),
        ("Attachment type selects a storage implementation.","Factory pattern · Interface-based integration","AttachmentStorageFactory routes images and videos to their dedicated Cloudinary implementations, and documents or logs to file storage. The upload command asks the factory through IAttachmentStorageFactory.","The use case can select storage behavior through an interface while infrastructure owns the provider-specific implementation.",C+"Infrastructure/FilesStorage/Factory/AttachmentStorageFactory.cs"),
        ("The persistence model declares its access paths.","EF Core · Indexes · Inheritance mapping","WorkItemConfiguration defines project-based composite indexes for sprint/creation time, type, status, assignee, priority, and creation time. It also declares a unique code index and a discriminator for concrete work-item entity types.","The database model expresses uniqueness, query access paths, and work-item specialization explicitly. These declarations do not claim a measured performance gain.",C+"Infrastructure/Persistence/Configurations/WorkItemConfiguration.cs"),
        ("Team membership goes through the domain model.","Encapsulation · Repository mapping","TeamsRepository converts the persisted team to its domain model before adding or removing members. Team rejects additions to inactive or full teams and prevents removal of the current lead; the repository then updates member rows and maps the domain state back.","The repository applies the membership rules when synchronizing database entities.",C+"Infrastructure/Persistence/Repositories/TeamsRepository.cs"),
        ("Estimation has an explicit vocabulary.","Domain value constraints · Typed specialization","UserStory.Estimate accepts only 1, 2, 3, 5, 8, or 13 story points. Constructors and the work-item update path call this method rather than accepting an arbitrary estimate directly.","Creation and editing share the same allowed estimation values.",C+"Domain/Models/UserStory.cs")
    ]),
    ]
    result=['<p>These choices connect the platform’s domain, persistence, access rules, and user experience. Open a decision to explore its implementation and the responsibility it serves.</p>']
    number=0
    for group_index,(name,entries) in enumerate(groups):
        result.append(f'<div class="decision-group"><h3>{name}</h3>')
        for title,skill,text,effect,url in entries:
            number+=1
            opened=' open' if group_index==1 and title.startswith('A release') else ''
            result.append(f'<details class="decision-detail"{opened}><summary><span class="decision-index mono">{number:02}</span><span><strong>{title}</strong><small>{skill}</small></span><span class="decision-toggle" aria-hidden="true">+</span></summary><div class="decision-body"><p>{text}</p><p class="decision-effect"><strong>What this supports</strong>{effect}</p>{ext(url,"Explore the implementation","source-link")}</div></details>')
        result.append('</div>')
    return ''.join(result)


